INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (1, 'postutme-fee', 2, 2, 'How much is the EBSU Post-UTME form?', 'For the 2026/2027 admission exercise, the Post-UTME fee is **N2,000.00** and it is non-refundable.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 1);
