INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (2, 'postutme-dates', 2, 2, 'When does the EBSU Post-UTME application open and close?', 'The 2026/2027 notice gave the Post-UTME application period (for UTME and Direct Entry candidates) as **22 May 2026 to 22 June 2026**.\n\nCheck ebsu.edu.ng for a newer notice before you plan for a later session.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 1);
