INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (3, 'postutme-eligibility', 2, 2, 'Who can apply for the EBSU Post-UTME?', 'The 2026/2027 exercise was for candidates who chose EBSU as first choice (or were willing to change to EBSU) and scored **150 or above** in the 2026/2027 UTME.\n\nCandidates awaiting NABTEB O''level, WAEC (May/June) or NECO (June/July) 2026 results were also allowed to apply.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (3, 'post utme requirements');
