INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (4, 'postutme-steps', 2, 2, 'How do I apply for the EBSU Post-UTME?', 'The 2026/2027 notice gives these steps:\n1. Open the EBSU Post-UTME portal and choose Online Application Forms from the quick menu.\n2. Select the Post-UTME form, or the Direct Entry form if you are a DE candidate.\n3. Enter your JAMB registration number and log in. This generates your payment invoice.\n4. Pay at any bank, or online with your debit card.\n5. Return to the portal and complete the form using your own email address and phone number.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 1);
