INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (6, 'name-mismatch', 2, 2, 'What happens if my name is different on my O''level and JAMB results?', 'Your name must be the same on your O''level certificate, your UTME result and your other registration documents. The university says any inconsistency in the name is unacceptable and may lead to disqualification.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 0);
