INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (7, 'cutoff-general', 2, 2, 'What is the EBSU cut-off mark?', 'For the 2026/2027 admission exercise, the EBSU general cut-off mark is **150**.\n\nSome programmes need more, for example Medicine and Surgery 250, Law 240 and Nursing Science 230. Ask me about your course to see its cut-off.', 'https://ebsu.edu.ng/ebsu-post-utme-approved-cut-off-mark-for-2026-2027-admission-exercise/', 'Approved cut-off marks, 2026/2027', 1);
