INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (14, 'cutoff-engineering', 2, 2, 'What is the cut-off mark for Engineering courses?', 'Approved minimum scores for 2026/2027:\n- Chemical Engineering: **170**\n- Electrical and Electronics Engineering: **170**\n- Civil Engineering: **160**\n- Environmental Sciences courses: **150**', 'https://ebsu.edu.ng/ebsu-post-utme-approved-cut-off-mark-for-2026-2027-admission-exercise/', 'Approved cut-off marks, 2026/2027', 0);
