INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (17, 'cutoff-others', 2, 2, 'What is the cut-off mark for Education, Agriculture and other courses?', 'For 2026/2027 these all use the general minimum of **150**:\n- Faculty of Education courses\n- Faculty of Agriculture and Natural Resources Management courses\n- Science courses other than Computer Science\n- Social Sciences and Humanities courses other than Mass Communication\n- Management courses other than Accountancy\n- Environmental Sciences courses', 'https://ebsu.edu.ng/ebsu-post-utme-approved-cut-off-mark-for-2026-2027-admission-exercise/', 'Approved cut-off marks, 2026/2027', 0);
