INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (18, 'admission-status', 1, 2, 'How do I check my EBSU admission status?', 'Go to the Check Admission Status page on the EBSU portal (portal.ebsu.edu.ng), select the session and enter your JAMB registration number.\n\nThe admission procedures page also says you can log on to www.ebsu.edu.ng/app and click "check admission status". Undergraduate, postgraduate and JUPEB admissions each have their own status check on the portal.', 'https://ebsu.edu.ng/admission-procedures/', 'Admission procedures page and EBSU portal', 1);
