INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (19, 'merit-list', 1, 2, 'Has the EBSU merit admission list been released?', 'Yes. The **1st batch of merit admission for the 2026/2027 session** (as at 4 August 2026) was posted on the EBSU website on 6 August 2026.\n\nThe list is a PDF arranged by course. Search it for your JAMB registration number, then confirm on the portal''s Check Admission Status page. Watch ebsu.edu.ng for later batches.', 'https://ebsu.edu.ng/first_batch_of_merit_list_2026/', 'Posted 6 August 2026', 1);
