INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (20, 'caps-acceptance', 1, 2, 'How long do I have to accept my admission on JAMB CAPS?', 'For 2026/2027, you must accept the offer of admission on CAPS or the JAMB portal **within two (2) weeks**.\n\nIf you do not accept it within that period, the offer is withdrawn.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 0);
