INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (21, 'acceptance-steps', 1, 2, 'How do I accept my admission and print my admission letter?', 'The admission procedures page gives these steps:\n1. Create a portal account at www.ebsu.edu.ng/portal. Choose New Student (Current Year 1), enter your JAMB registration number and click Verify.\n2. Update your personal profile.\n3. Click Acceptance fees and choose Get Acceptance Invoice.\n4. Print the invoice and pay at any bank, or pay online.\n5. Return to the portal and print your acceptance letter and online admission letter.\n6. Take the electronic receipt to the EBSU Bursary Unit to collect your original Bursary receipt.\n\nRemember to also accept the offer on JAMB CAPS.', 'https://ebsu.edu.ng/admission-procedures/', 'Admission procedures page', 1);
