INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (22, 'clearance-documents', 1, 2, 'What documents do I need for documentation at the Admission Unit?', 'After paying the acceptance fee, go to the Admission Unit for documentation with these originals:\n- JAMB result slip\n- O''level result slip (SSCE/NECO or NABTEB)\n- Pre-degree (PD) result slip, where applicable\n- Printout of the acceptance fee acknowledgement slip\n- L.G.A. identification letter\n- EBSU Bursary receipt for the acceptance fee\n- Birth certificate or age declaration', 'https://ebsu.edu.ng/admission-procedures/', 'Admission procedures page', 1);
