INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (23, 'e-clearance', 1, 2, 'Can I do my clearance online?', 'Yes. EBSU has an e-clearance page at services.ebsu.edu.ng/clearance. You submit the required documents, track approvals and finish clearance online without visiting offices in person.\n\nThe services site also has a Clearance FAQ page.', 'https://services.ebsu.edu.ng/clearance', 'EBSU e-services site', 0);
