INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (24, 'application-documents', 1, 2, 'What documents do I need to fill the admission form online?', 'The registration portal lists:\n- A passport photograph\n- O''level certificates or results (scanned copies)\n- Tertiary institution result details, for Direct Entry candidates\n- JAMB result details, for Year 1 candidates', 'https://iportal.ebsu.edu.ng/app/admissions/start_application', 'EBSU registration portal', 0);
