INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (25, 'olevel-upload', 1, 2, 'Do I need to upload my O''level result before I am admitted?', 'Yes. Candidates must upload their O''level results to **both the EBSU portal and the JAMB portal** before they can be recommended for admission.\n\nDirect Entry candidates must also ask their institutions to verify their A level certificate on the JAMB portal.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice', 0);
