INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (26, 'olevel-requirements', 1, 2, 'How many O''level credits do I need for admission into a science course?', 'EBSU science department pages ask for at least **five O''level credit passes in not more than two sittings**, including English Language and Mathematics plus the subjects for the course.\n\nFor example, Biochemistry asks for credits in English Language, Mathematics, Chemistry, Biology and Physics. Check your department''s page on ebsu.edu.ng for its exact subjects.', 'https://ebsu.edu.ng/department-of-biochemistry/', 'Department of Biochemistry page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (26, 'how many credits do i need');
