INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (27, 'cs-requirements', 1, 2, 'What are the admission requirements for Computer Science?', 'The Department of Computer Science lists the UTME subjects as **English, Mathematics, Physics, and either Chemistry or Biology**, with credit passes required in those subjects.\n\nThe 2026/2027 cut-off mark for Computer Science is 170. Direct Entry students start at 200 level.', 'https://ebsu.edu.ng/department-of-computer-science/', 'Department of Computer Science page', 0);
