INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (28, 'direct-entry', 1, 2, 'How does Direct Entry admission work at EBSU?', 'Direct Entry candidates who chose EBSU apply with the Direct Entry form on the Post-UTME portal and are screened online. They must ask their institutions to verify their A level certificate on the JAMB portal.\n\nEntry requirements depend on the department. For example, in Computer Science and Biochemistry, Direct Entry students start at 200 level.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice and department pages', 0);
