INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (29, 'supplementary', 1, 2, 'Is there a supplementary admission form at EBSU?', 'The latest supplementary notice on the EBSU website is for **2025/2026**. It was for candidates who chose EBSU as first choice, scored 150 or above and had the required O''level credits. The fee was N10,050 and the portal was open from 1 September to 13 October 2025.\n\nIn 2024/2025 there was no supplementary admission into Law, Medicine and Surgery, Anatomy, Physiology, Medical Laboratory Sciences or Nursing Sciences. Watch ebsu.edu.ng for a 2026/2027 notice.', 'https://ebsu.edu.ng/2025-2026-application-form-for-supplementary-admission-is-out/', '2025/2026 supplementary notice', 0);
