INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (30, 'predegree', 1, 2, 'How is admission through pre-degree decided?', 'For 2025/2026, admission through pre-degree was by the **average of the JAMB score and the pre-degree score**.\n\nPre-degree candidates must still meet the minimum acceptable UTME pass.', 'https://ebsu.edu.ng/2025-2026-post-utme-application-screening/', '2025/2026 Post-UTME notice', 0);
