INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (31, 'jupeb', 1, 2, 'Does EBSU run a JUPEB programme?', 'Yes. EBSU''s JUPEB page (ebsu.edu.ng/jupeb) has the 2025/2026 application form, fee payment and full registration procedure.\n\nThe EBSU portal also has a JUPEB application form and a separate check for JUPEB admission status.', 'https://ebsu.edu.ng/jupeb/', 'JUPEB page, 2025/2026', 0);
