INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (32, 'wasp', 1, 2, 'Does EBSU have a part-time programme for workers?', 'Yes. EBSU set up its **Work and Study Programme (WASP)** and a weekend programme in 2000 for workers who want a university education while keeping their jobs.\n\nThe admissions portal lists a WASP/part-time admission application option. Ask the Registry for current WASP requirements and fees.', 'https://ebsu.edu.ng/about-ebsu/', 'About EBSU page and admissions portal', 0);
