INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (33, 'matriculation', 1, 1, 'When is the EBSU matriculation ceremony?', 'The **28th Matriculation Ceremony** (for 2025/2026 freshmen) held on Saturday, 28 February 2026 at 11am at the Matriculation Grounds, EBSU Main Campus. Freshmen were asked to meet their Faculty Officers for final preparations.\n\nWatch ebsu.edu.ng for the date of the next matriculation.', 'https://ebsu.edu.ng/28th-matriculation-ceremony/', 'Invitation dated February 2026', 0);
