INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (34, 'acceptance-fee', 3, 3, 'How much is the EBSU acceptance fee?', 'The latest acceptance fee table on the EBSU website is for the **2022/2023 session**:\n- Medicine and Surgery, Law, Nursing Science and Medical Laboratory Science: **N50,050**\n- All other courses: **N30,050**\n\nThe fee is non-refundable. A newer amount has not been published on the website, so confirm the current figure with the Bursary Unit before you pay.', 'https://ebsu.edu.ng/admission-procedures/', '2022/2023 fee table on the admission procedures page', 1);
