INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (35, 'fees-instalments', 3, 3, 'Can I pay my school fees in instalments?', 'Yes, according to a university memo of August 2023: from the **2023/2024 session**, students may pay their session''s fees in **two instalments** and still take part in academic activities.\n\nAsk the Bursary Unit to confirm that the policy still applies to your session.', 'https://mail.ebsu.edu.ng/feepayment.php', 'Memo dated 14 August 2023', 1);
