INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (36, 'fees-how-to-pay', 3, 3, 'How do I pay EBSU fees?', 'EBSU payments go through the **Remita** platform. Official payment procedures work like this: you generate an invoice on the EBSU portal, then pay at any bank with the Remita number, or online with a credit card, MasterCard or Verve card.\n\nKeep your receipt. Some steps, such as acceptance, also need an original receipt from the Bursary Unit. Ask the Bursary Unit for the exact steps for your school fees.', 'https://mail.ebsu.edu.ng/supp_payment.php', 'EBSU payment procedure (2022/2023 notice)', 0);
