INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (37, 'school-fees-amount', 3, 3, 'How much is EBSU school fees?', 'I don''t have the current school fee amounts yet. The EBSU website has a "Schedule of Fees" link under its Admission menu, and fees are generated and paid on the student portal through Remita.\n\nFor the exact amount for your course and level, contact the Bursary Unit.', 'https://ebsu.edu.ng/', 'Admission menu on ebsu.edu.ng', 0);
