INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (38, 'portal-account', 4, 6, 'How do I create my EBSU portal account as a new student?', 'Log on to www.ebsu.edu.ng/portal, choose **New Student (Current Year 1)**, enter your JAMB registration number and click Verify. This generates your default account details.\n\nThen update your personal profile. The iPortal guide for new students also covers uploading your passport photograph and generating the acceptance fee invoice.', 'https://ebsu.edu.ng/admission-procedures/', 'Admission procedures page', 1);
