INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (39, 'portal-login', 4, 6, 'How do I log in to the EBSU student portal?', 'The student login page is at https://iportal.ebsu.edu.ng/portal/.\n\nThe older portal at portal.ebsu.edu.ng accepts your Matric number, JAMB number or entry registration number to log in.', 'https://iportal.ebsu.edu.ng/portal/', 'EBSU iPortal login page', 1);
