INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (40, 'portal-password', 4, 6, 'I forgot my EBSU portal password. What do I do?', 'Use the **"Forgot your password?"** link on the iPortal login page (iportal.ebsu.edu.ng/portal).\n\nIf that does not work, email ictsupport@ebsu.edu.ng or call +2348037550845 or +2348064087963.', 'https://iportal.ebsu.edu.ng/portal/', 'EBSU iPortal login page', 0);
