INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (41, 'portal-support', 4, 6, 'Who do I contact if I have a problem with the EBSU portal?', 'For admission or portal problems, email **ictsupport@ebsu.edu.ng** or call:\n- +2348064087963\n- +2348037550845\n- +2348067664449', 'https://iportal.ebsu.edu.ng/app/admissions/support', 'EBSU registration portal support page', 1);
