INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (42, 'online-services', 4, 6, 'What online services does EBSU have?', 'The EBSU services site (services.ebsu.edu.ng) offers e-clearance, e-transcript, e-learning and seminar courses, and its login page lists eClearance, eBursary, eRecords and eTranscript.\n\nEBSU also runs an online entrepreneurship platform at elearning.ebsu.edu.ng.', 'https://services.ebsu.edu.ng/', 'EBSU e-services site', 0);
