INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (43, 'faculties-list', 5, 1, 'What faculties does EBSU have?', 'The official faculties page lists these faculties:\n- Science\n- Agricultural and Natural Resource Management\n- Health Science and Technology\n- Social Sciences and Humanities\n- Basic Medical Sciences\n- Clinical Medicine\n- Education\n- Management Sciences\n- Law\n- Engineering\n\nAdmission notices for 2026/2027 also group Medicine and Surgery, Anatomy and Physiology under a Faculty of Medicine, and use the name Faculty of Engineering and Environmental Science.', 'https://ebsu.edu.ng/faculties/', 'Faculties page, 2026', 1);
