INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (44, 'science-departments', 5, 1, 'What departments are in the Faculty of Science?', 'The faculties page lists nine departments in the Faculty of Science:\n- Applied Biology\n- Applied Microbiology\n- Biochemistry\n- Biotechnology\n- Computer Science\n- Geology / Exploration\n- Industrial Chemistry\n- Industrial Mathematics & Statistics\n- Industrial Physics', 'https://ebsu.edu.ng/faculties/', 'Faculties page, 2026', 1);
