INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (45, 'fssh-departments', 5, 1, 'What departments are in the Faculty of Social Sciences and Humanities?', 'The faculties page lists these under Social Sciences and Humanities:\n- Economics\n- English Language / Literature\n- History & International Relations\n- Language & Linguistics\n- Library & Information Science\n- Mass Communication\n- Philosophy & Religion\n- Political Science\n- Psychology\n- Social Works\n- Sociology and Anthropology\n\nThe 2025/2026 Post-UTME notice also lists B.A Theatre Art and B.A Film Production.', 'https://ebsu.edu.ng/faculties/', 'Faculties page, 2026', 0);
