INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (46, 'management-departments', 5, 1, 'What courses are in the Faculty of Management Sciences?', 'The Faculty of Management Sciences lists six programmes:\n- Public Administration\n- Business Management\n- Marketing\n- Accountancy\n- Banking and Finance\n- Entrepreneurship', 'https://ebsu.edu.ng/2025-2026-post-utme-application-screening/', '2025/2026 Post-UTME notice', 0);
