INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (47, 'engineering-departments', 5, 1, 'What courses are in the Faculty of Engineering and Environmental Science?', 'The core engineering departments are Chemical Engineering, Civil Engineering and Electrical/Electronics Engineering.\n\nThe 2026/2027 Post-UTME notice also lists Architecture, Building, Environmental Management and Estate Management under the Faculty of Engineering and Environmental Science. The 2024/2025 advert listed Quantity Surveying and Urban & Regional Planning under Environmental Sciences.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice and 2024/2025 advert', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (47, 'engineering courses in ebsu');
