INSERT INTO qa_variants (qa_id, phrasing) VALUES (47, 'does ebsu offer electrical engineering');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (48, 'agric-departments', 5, 1, 'What departments are in the Faculty of Agriculture and Natural Resources Management?', 'Official listings show six departments:\n- Agricultural Economics, Management & Extension\n- Crop Science and Landscape Management\n- Soil and Environmental Management\n- Food Science and Technology\n- Fisheries and Aquaculture\n- Animal Science', 'https://ebsu.edu.ng/2025-2026-post-utme-application-screening/', '2025/2026 Post-UTME notice and faculties page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (48, 'agriculture courses in ebsu');
