INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (49, 'education-departments', 5, 1, 'What departments are in the Faculty of Education?', 'The faculties page lists:\n- Business Education\n- Educational Foundations\n- Guidance & Counselling\n- Home Economics\n- Human Kinetics & Health Education\n- Science Education\n- Technology & Vocational Education', 'https://ebsu.edu.ng/faculties/', 'Faculties page, 2026', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (49, 'education courses in ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (49, 'faculty of education departments');
