INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (50, 'law-departments', 5, 1, 'What departments are in the Faculty of Law?', 'The faculties page lists Civil Law, International Law & Jurisprudence, Private & Property Law and Public Law under the Faculty of Law, with Business Law listed nearby.\n\nIn 2024, the EBSU Faculty of Law came first in Africa at the 33rd Christof Heyns African Moot Court Competition in Kigali, Rwanda.', 'https://ebsu.edu.ng/faculties/', 'Faculties page, 2026', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (50, 'law departments');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (50, 'faculty of law ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (50, 'does ebsu offer law');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (51, 'health-courses', 5, 1, 'What courses are in the Faculty of Health Science and Technology?', 'The 2026/2027 Post-UTME notice lists **Medical Laboratory Science** and **Nursing Science** under the Faculty of Health Science and Technology.\n\nThe faculty was set up in 2002 and started in the 2002/2003 session with those two departments.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice and About EBSU page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (51, 'does ebsu offer nursing');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (51, 'health science courses in ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (51, 'medical laboratory science in ebsu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (52, 'medicine-structure', 5, 1, 'Does EBSU offer Medicine and Surgery?', 'Yes. The 2026/2027 Post-UTME notice groups **Medicine and Surgery, Anatomy and Physiology** under a Faculty of Medicine.\n\nThe faculties page also lists a Faculty of Basic Medical Sciences (Anatomy, Physiology) and a Faculty of Clinical Medicine, and the university refers to an EBSU College of Health Sciences.', 'https://ebsu.edu.ng/2026-2027-post-utme-application-screening/', '2026/2027 Post-UTME notice and faculties page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (52, 'does ebsu offer medicine');
