INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (53, 'gst-courses', 5, 1, 'What are the GST courses at EBSU?', 'Department curricula list General Studies (GST) courses, for example:\n- GST 101 Use of English I\n- GST 102 Philosophy and Logic\n- GST 103 Nigerian People and Culture\n- GST 107 Use of English II\n- Entrepreneurship courses from 200 level, such as GST 201 or GST 202\n- GST 222 Peace and Conflict Resolution\n\nCourse codes and titles differ slightly between departments, so check your department''s curriculum.', 'https://ebsu.edu.ng/courses/applied-sciences/', 'Department curricula', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (53, 'general studies courses');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (53, 'gst 101');
