INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (54, 'microbiology-attachment', 5, 1, 'Do Applied Microbiology students go for industrial training?', 'Yes. Applied Microbiology students do a **compulsory six-month professional attachment after 300 level**, in industries such as food and beverage companies or in medical and health institutions.', 'https://ebsu.edu.ng/department-of-applied-microbiology/', 'Department of Applied Microbiology page', 0);
