INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (55, 'directorates', 5, 1, 'What directorates and centres does EBSU have?', 'The directorates page lists:\n- ICT/Research Centre\n- Biotech Research and Development Centre\n- Directorate of General Studies\n- Entrepreneur Development Centre\n- Research, Innovation and Commercialization\n- Directorate of Works\n- Directorate of Consultancy', 'https://ebsu.edu.ng/directorates/', 'Directorates page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (55, 'ebsu directorates');
