INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (56, 'check-results', 6, 4, 'How do I check my EBSU result?', 'Log in to the EBSU student portal (portal.ebsu.edu.ng) and use the **Sessional Result** link. The portal also has a View Pre-Degree Result option.\n\nIf your result is not showing, ask your department or the Records Unit.', 'https://portal.ebsu.edu.ng/index.html', 'EBSU portal', 1);
