INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (57, 'transcript-apply', 6, 4, 'How do I apply for my EBSU transcript?', 'Apply online on the e-transcript portal at **iportal.ebsu.edu.ng/transcript**. You do not need to visit the campus.\n\n1. Generate your payment invoice on the e-transcript platform.\n2. Pay online with your debit card, then verify the payment RRR code.\n3. Fill in the application and upload your last statement of result.\n4. Note your application number so you can track the request.', 'https://iportal.ebsu.edu.ng/transcript/', 'EBSU e-transcript portal', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (57, 'how to get transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (57, 'transcript application ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (57, 'how i go collect my transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (57, 'request transcript online');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (57, 'e transcript portal');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (57, 'where do i apply for transcript');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (58, 'transcript-requirements', 6, 4, 'What do I need to apply for a transcript?', 'You need:\n- A valid email address and mobile number\n- Your home contact address\n- The receiving school''s address as the destination (not a home or office address)\n- Your last statement of result, uploaded as a .pdf or .docx file. Image files are rejected.', 'https://iportal.ebsu.edu.ng/transcript/site/start_application', 'EBSU e-transcript portal', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (58, 'transcript requirements');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (58, 'documents for transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (58, 'what file format for statement of result');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (59, 'transcript-delivery', 6, 4, 'How long does it take to get an EBSU transcript?', 'Requests are processed in the order they arrive. After the Records Unit finishes processing, **E-JUSGLOBAL Agency delivers the transcript within 48 hours**.\n\nTrack your request with the application number you get when you apply. Visits to the Records Office are by invitation only.', 'https://iportal.ebsu.edu.ng/transcript/site/about_transcripts', 'EBSU e-transcript portal', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (59, 'how many days for transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (59, 'who delivers transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (59, 'track my transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (59, 'can i visit the records office');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (59, 'transcript processing time');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (60, 'transcript-recipients', 6, 4, 'Where can my transcript be sent?', 'Transcripts can only be sent to equivalent academic institutions, professional bodies, scholarship boards or embassies, for academic purposes.\n\nUse the receiving institution''s address, not a home or office address.', 'https://iportal.ebsu.edu.ng/transcript/site/about_transcripts', 'EBSU e-transcript portal', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (60, 'can i send transcript to myself');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (60, 'can transcript be sent to my house');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (60, 'who can receive transcript');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (61, 'transcript-fast-track', 6, 4, 'Can someone help me process my transcript faster?', 'No. Generate every invoice on the e-transcript platform and pay online only. The portal warns applicants never to pay any individual or organisation that claims it can speed up processing.', 'https://iportal.ebsu.edu.ng/transcript/', 'EBSU e-transcript portal', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (61, 'pay someone to speed up transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (61, 'agent for transcript');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (61, 'faster transcript processing');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (62, 'document-verification', 6, 6, 'How do I verify an EBSU certificate or result?', 'Pay the verification fee on Remita:\n1. Go to Remita.net and open Bills and Purchases, then Pay Billers.\n2. Search for Ebonyi State University.\n3. Select Treasury Sundry Fees, then Certificate Verification Fees.\n4. Complete the remaining fields and submit.\n\nThe contact on the verification page is ictdirector@ebsu.edu.ng.', 'https://ebsu.edu.ng/document-verification/', 'Document verification page', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (62, 'certificate verification');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (62, 'result verification ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (62, 'how to confirm ebsu certificate');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (62, 'verify degree');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (63, 'pg-dates-fee', 7, 7, 'When is the EBSU postgraduate admission form for 2026/2027?', 'Applications for 2026/2027 postgraduate admission ran from **1 May 2026 to 30 June 2026**. The application fee was **N10,050.00**, paid after generating an invoice. The School of Postgraduate Studies says Remita is the only payment platform.', 'https://ebsu.edu.ng/postgraduate-admissions-for-2026-2027-academic-session/', '2026/2027 postgraduate admission notice', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (63, 'pg form ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (63, 'postgraduate application deadline');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (63, 'masters form ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (63, 'how much is pg form');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (63, 'spgs form 2026');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (64, 'pg-how-to-apply', 7, 7, 'How do I apply for postgraduate studies at EBSU?', '1. Go to the PG application login at portal.ebsu.edu.ng/PG/Applications/PGApplicationLogin.aspx.\n2. Enter your phone number and select the 2026/2027 session.\n3. Fill the form, generate the invoice and pay the N10,050.00 fee.\n4. Return to the portal, complete the application, upload the originals of your documents and submit.\n\nYou also need reference letters from **three referees**, two of them academics who know your academic ability. Your previous institution must send your transcript directly to spgs@ebsu.edu.ng before applications close.', 'https://ebsu.edu.ng/postgraduate-admissions-for-2026-2027-academic-session/', '2026/2027 postgraduate admission notice', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (64, 'how to apply for masters');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (64, 'pg application procedure');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (64, 'how do i apply for phd');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (64, 'postgraduate referees');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (65, 'pg-requirements', 7, 7, 'What are the requirements for a PGD or Masters at EBSU?', 'From the School of Postgraduate Studies:\n- **PGD:** a Bachelor''s degree from EBSU or another recognised institution (third class holders are normally admitted), or an HND at Lower Credit in a related discipline with 3 years of relevant work experience.\n- **Masters (MSc):** an appropriate degree with at least a good second class honours, or an EBSU PGD (or equivalent) with a CGPA of at least 2.5 on the 5-point scale or a 60% average.\n\nAll applicants need at least a credit in O''level English Language; science programmes also need a credit in Mathematics.', 'https://spgs.ebsu.edu.ng/admissionreq.php', 'SPGS admission requirements', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (65, 'masters requirements');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (65, 'pgd requirements');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (65, 'can i do masters with third class');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (65, 'can hnd holders do pgd');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (65, 'msc entry requirements');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (66, 'pg-phd', 7, 7, 'What are the requirements for a PhD at EBSU?', 'You need a Master''s degree in the proposed area of study with a **CGPA of not less than 3.50 on the 5-point scale**. Check your department''s postgraduate page for any extra requirements.', 'https://spgs.ebsu.edu.ng/admissionreq.php', 'SPGS admission requirements', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (66, 'phd requirements');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (66, 'phd entry cgpa');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (66, 'can i do phd with my masters');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (67, 'pg-contact', 7, 7, 'How do I contact the EBSU School of Postgraduate Studies?', 'School of Postgraduate Studies:\n- Email: spgsebsu@ebsu.edu.ng\n- Mobile: +234 (0)810 231 8225\n- Dean: Iroha, Ifeanyichukwu Romanus\n\nThe 2026/2027 notice asks for transcripts to be sent to spgs@ebsu.edu.ng.', 'https://spgs.ebsu.edu.ng/deanspgs.php', 'SPGS website', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (67, 'spgs email');
