INSERT INTO qa_variants (qa_id, phrasing) VALUES (67, 'who is the dean of postgraduate school');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (68, 'pg-id-card', 7, 7, 'How do postgraduate students pay for their ID card?', 'On Remita.net, go to Bills and Purchases, then Pay Billers. Enter EBONYI STATE UNIVERSITY as the biller, choose the postgraduate service and select **PG STUDENTS ID CARD FEES**. Fill in the other details, then submit to pay or to generate a payment invoice.', 'https://spgs.ebsu.edu.ng/studentidcard.php', 'SPGS student ID card page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (68, 'pg id card');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (68, 'postgraduate id card fee');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (68, 'how to get id card as pg student');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (69, 'pg-programmes', 7, 7, 'What postgraduate programmes does EBSU offer?', 'Department pages on the SPGS site show PGD, MSc and PhD programmes, for example in Agricultural Economics, Food Science and Technology, Industrial Physics, Fisheries and Aquaculture, and Applied Biology. The SPGS homepage lists PhDs in Biochemistry/Biotechnology, Computer Science, Chemistry and Industrial Physics.\n\nThis is not a full list; check spgs.ebsu.edu.ng for your department.', 'https://spgs.ebsu.edu.ng/', 'SPGS website', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (69, 'pg courses ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (69, 'does ebsu offer phd in computer science');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (69, 'masters programmes in ebsu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (70, 'vc', 9, 1, 'Who is the Vice-Chancellor of EBSU?', '**Professor Michael Ugota Awoke** is the Vice-Chancellor of Ebonyi State University. He issued the invitation to the 28th Matriculation Ceremony in February 2026.', 'https://ebsu.edu.ng/28th-matriculation-ceremony/', 'Homepage and matriculation invitation, 2026', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (70, 'who is the vc of ebsu');
