INSERT INTO qa_variants (qa_id, phrasing) VALUES (70, 'who is the head of the university');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (70, 'who is in charge of ebsu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (71, 'registrar', 9, 1, 'Who is the Registrar of EBSU?', 'The Registrar page names **Ugochinyere Mba Uka** as Registrar of Ebonyi State University. The Registrar''s office email is registrar@ebsu.edu.ng.', 'https://ebsu.edu.ng/registrar/', 'Registrar page, 2025', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (71, 'ebsu registrar');
