INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (72, 'principal-officers', 9, 1, 'Who are the Deputy Vice-Chancellors and the University Librarian?', 'From the EBSU website:\n- Deputy Vice-Chancellor (Academics): Prof. Ike-Elechi Ogba\n- Deputy Vice-Chancellor (Administration): Prof. Michael Ajanwachukwu\n- University Librarian: Dr. Victoria Nwali Chukwu\n- Dean, School of Postgraduate Studies: Iroha, Ifeanyichukwu Romanus', 'https://ebsu.edu.ng/deputy-vice-chancellor-academics/', 'Principal officer pages, 2025 and 2026', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (72, 'dvc academics');
