INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (73, 'history', 9, 1, 'When was EBSU established?', 'EBSU traces its origin to the Anambra State University of Science and Technology (ASUTECH), set up on 30 July 1980.\n\nAfter Ebonyi State was created in 1996, the Abakaliki campus of ESUT was upgraded to **Ebonyi State University College** (Edict No. 5 of 1998), with Prof. Fidelis Ogah as first Rector. It became a full university under the **Ebonyi State University Law No. 7 of 1999**, which received the governor''s assent on 14 January 2000. Prof. Ogah became the first Vice-Chancellor.', 'https://ebsu.edu.ng/about-ebsu/', 'About EBSU page', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (73, 'history of ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (73, 'when was ebonyi state university founded');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (73, 'how old is ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (73, 'who was the first vc of ebsu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (74, 'vision-mission', 9, 1, 'What is the vision and mission of EBSU?', '**Vision:** To rank among the best citadels of learning in the world with excellence in learning, research and community service.\n\n**Mission:** To provide a conducive atmosphere for teaching, learning, research and rapid development in order to transform the hitherto, untapped, abundant unskilled, human resources in Ebonyi state into skilled power.', 'https://ebsu.edu.ng/about-ebsu/', 'About EBSU page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (74, 'ebsu vision');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (74, 'ebsu mission statement');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (74, 'what does ebsu aim to achieve');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (75, 'location', 9, 1, 'Where is EBSU located?', 'Ebonyi State University is in **Abakaliki, Ebonyi State**, on the Enugu - Abakaliki Road (481101, Abakaliki). The postal address is P.M.B. 053, Abakaliki, Ebonyi State, Nigeria.', 'https://ebsu.edu.ng/contact-us/', 'Contact Us page', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (75, 'ebsu address');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (75, 'where is ebonyi state university');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (75, 'ebsu location');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (75, 'how do i find ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (75, 'ebsu postal address');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (76, 'campuses', 9, 1, 'What campuses does EBSU have?', 'University pages mention:\n- **EBSU Main Campus**, where the Matriculation Grounds are\n- **CAS (College of Agricultural Sciences) Campus**, home of the School of Postgraduate Studies Complex\n- **Ishieke campus**, where a new Engineering and Environmental Sciences faculty building was announced in 2025\n\nThe website does not say which faculties sit on each campus.', 'https://ebsu.edu.ng/28th-matriculation-ceremony/', 'Matriculation invitation, International Office and 2025 news', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (76, 'ebsu campuses');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (76, 'where is cas campus');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (76, 'ishieke campus');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (76, 'main campus ebsu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (77, 'student-population', 9, 1, 'How many students does EBSU have?', 'The website does not publish a total enrolment figure. The library page says it serves a **student population of 16,500** and has a total seating capacity of 10,000.', 'https://ebsu.edu.ng/physical-library/', 'Physical library page, 2026', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (77, 'ebsu student population');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (77, 'number of students in ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (77, 'how big is ebsu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (78, 'library', 8, 9, 'What are the EBSU library opening hours?', 'The Central Library (a two-storey building) is open **8:00 AM to 4:00 PM**.\n\nTo use the physical and electronic library, you must have completed your EBSU registration and also register with the library. Enquiries: librarian@ebsu.edu.ng.', 'https://ebsu.edu.ng/physical-library/', 'Physical library page, 2026', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (78, 'library hours');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (78, 'when does the library open');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (78, 'how do i use the library');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (78, 'library registration');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (78, 'where is the ebsu library');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (79, 'e-library', 8, 9, 'Does EBSU have an e-library?', 'Yes. The E-Library is on the **2nd floor** of the library. It offers subscribed databases such as EBSCOhost, ProQuest, JSTOR, Law Pavilion and Research4Life (HINARI, AGORA, AORE, ARDI, GOALI), plus free open-access resources.', 'https://ebsu.edu.ng/electronic-digital-library/', 'Electronic library page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (79, 'e library ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (79, 'online journals ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (79, 'jstor access');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (79, 'where is the e-library');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (80, 'health-safety', 8, 10, 'What number do I call for campus security or health services?', 'The university''s Health and Safety page lists **08037550845** and **08064087963** for Police, Institution Security and Health Services, at Enugu - Abakaliki Road, Abakaliki. The page also has a Counselling & Psychological Services section.', 'https://ebsu.edu.ng/health-and-safety/', 'Health and Safety page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (80, 'emergency number ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (80, 'campus police number');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (80, 'health centre number');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (80, 'who do i call if i am sick on campus');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (80, 'security number');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (81, 'international-office', 8, 8, 'How do I contact the EBSU International Office?', 'The International Office for Partnerships and Cooperation promotes research and professional collaboration with other universities and institutions.\n- Email: internationaloffice@ebsu.edu.ng (replies in 2 to 3 working days)\n- Phone: +234 (0)703 922 0960\n- Office: School of Postgraduate Studies Complex, CAS Campus', 'https://mail.ebsu.edu.ng/international-office.php', 'International Office page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (81, 'international students ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (81, 'international office email');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (81, 'study abroad ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (81, 'partnerships office');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (82, 'scholarships', 8, 1, 'Are there scholarships at EBSU?', 'The university runs the **ORPHAN intra-Africa academic mobility project (2023 to 2027)**, with MSc, staff and trainee scholarships; its third call ran from 16 January to 10 March 2026. EBSU also has a scholarship page on its website.\n\nCheck the scholarship page on ebsu.edu.ng for current calls.', 'https://orphanproject.ebsu.edu.ng/', 'ORPHAN project site', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (82, 'ebsu scholarship');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (82, 'how to get scholarship in ebsu');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (82, 'orphan project scholarship');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (82, 'scholarship for masters abroad');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (83, 'ict-centre', 8, 6, 'What does the EBSU ICT and Research Centre do?', 'The ICT and Research Centre provides IT training and research support to the university community and the Ebonyi State public. Its services include journal publication, open educational resources, conferences and workshops, the e-library, the institutional repository and document verification.', 'https://ebsu.edu.ng/ict-and-research-center/', 'ICT and Research Centre page', 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (83, 'ict centre services');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (83, 'ict and research centre');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (83, 'where can i get ict training');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (84, 'contact-general', 10, 1, 'What are EBSU''s contact email and phone number?', '- General email: registrar@ebsu.edu.ng\n- Information: info@ebsu.edu.ng\n- Phone: 0806 408 7963\n- ICT Director: ictdirector@ebsu.edu.ng\n- Post: P.M.B. 053, Abakaliki, Ebonyi State, Nigeria', 'https://ebsu.edu.ng/contact-us/', 'Contact Us page', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (84, 'ebsu phone number');
