INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (85, 'contact-admissions', 10, 2, 'How do I contact the EBSU admissions office?', 'For admission and admission-portal issues, the registration portal gives:\n- Email: ictsupport@ebsu.edu.ng\n- Phone: +2348064087963, +2348037550845 or +2348067664449\n\nFor documentation after paying your acceptance fee, report in person to the Admission Unit.', 'https://iportal.ebsu.edu.ng/app/admissions/support', 'EBSU registration portal support page', 1);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (85, 'admission office phone number');
