INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (89, 'who-are-you', 11, NULL, 'Who are you?', 'I am the EBSU Enquiry Bot, a computer program built as a final year project. I answer student questions from a knowledge base made from official Ebonyi State University sources. I am not a person, and your questions are not sent to any outside service.', NULL, NULL, 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (89, 'what are you');
