INSERT INTO qa_variants (qa_id, phrasing) VALUES (89, 'who made you');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (90, 'what-can-you-do', 11, NULL, 'What can you help me with?', 'I can answer questions about:\n- Admission, Post-UTME and cut-off marks\n- Acceptance fee and how to pay fees\n- Portal accounts and logins\n- Faculties and departments\n- Results, transcripts and certificate verification\n- Postgraduate admission\n- Library, contacts and offices\n\nType your question in your own words, or pick one from Suggested questions.', NULL, NULL, 0);
INSERT INTO qa_variants (qa_id, phrasing) VALUES (90, 'what can you do');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (90, 'help');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (90, 'what do you know');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (90, 'what questions can i ask');
INSERT INTO qa_variants (qa_id, phrasing) VALUES (90, 'menu');
INSERT INTO qa_pairs (id, ref_key, category_id, office_id, question, answer, source_url, source_note, is_featured) VALUES (91, 'how-do-you-work', 11, NULL, 'How do you work?', 'I use natural language processing that runs on this computer, without the internet. I clean your message, fix common typos, translate Pidgin and short forms, then compare it with every stored question using TF-IDF and fuzzy matching.\n\nIf the best score is high enough, I give that answer. If not, I tell you which office to contact and save your question for the admin. Tap "How I matched this" under any reply to see the steps.', NULL, NULL, 0);
